INSERT INTO `deskripsi_aspek` (`aspek`, `nama_aspek`, `deskripsi`) VALUES
('N', 'Need to Finish Task', 'Kebutuhan untuk menyelesaikan tugas secara mandiri. Individu dengan skor N tinggi cenderung tekun dan tidak suka meninggalkan pekerjaan sebelum selesai.'),
('A', 'Need to Achieve', 'Kebutuhan untuk berprestasi dan mencapai hasil di atas rata-rata. Skor A tinggi menunjukkan ambisi dan orientasi pada kesuksesan.'),
('P', 'Need to Control Others', 'Kebutuhan untuk memimpin dan mengendalikan orang lain. Skor P tinggi menandakan kecenderungan untuk mengambil alih tanggung jawab dan memimpin.'),
('G', 'Hard Worker', 'Peran sebagai pekerja keras. Individu dengan skor G tinggi dilihat sebagai orang yang rajin, bekerja keras, dan memiliki stamina kerja yang baik.'),
('I', 'Leadership Role', 'Peran sebagai pemimpin. Skor I tinggi menunjukkan individu yang proaktif, mengambil inisiatif, dan seringkali menjadi pemimpin dalam kelompok.'),
('T', 'Need for Change', 'Kebutuhan akan perubahan dan variasi. Skor T tinggi menandakan individu yang mudah bosan dengan rutinitas dan menyukai hal-hal baru.'),
('V', 'Vigorous Type', 'Peran sebagai individu yang bersemangat dan penuh energi. Skor V tinggi menunjukkan vitalitas fisik dan semangat dalam beraktivitas.'),
('X', 'Need to be Noticed', 'Kebutuhan untuk diperhatikan. Individu dengan skor X tinggi ingin menonjol, menjadi pusat perhatian, dan diakui oleh lingkungan.'),
('S', 'Social Extension', 'Peran dalam hubungan sosial. Skor S tinggi menunjukkan individu yang ramah, mudah bergaul, dan memiliki banyak teman.'),
('B', 'Need to Belong to Group', 'Kebutuhan untuk menjadi bagian dari kelompok. Skor B tinggi menandakan individu yang butuh diterima dan merasa nyaman dalam kelompok.'),
('R', 'Theoretical Type', 'Peran sebagai pemikir teoretis. Individu dengan skor R tinggi suka berpikir mendalam, merenung, dan menganalisis masalah.'),
('D', 'Interest in Working with Details', 'Minat untuk bekerja dengan hal-hal rinci. Skor D tinggi menunjukkan ketelitian, perhatian pada detail, dan kecermatan.'),
('C', 'Organized Type', 'Peran sebagai individu yang teratur. Skor C tinggi menandakan kecenderungan untuk bekerja secara sistematis, rapi, dan terencana.'),
('E', 'Emotional Resistant', 'Peran dalam ketahanan emosional. Skor E tinggi menunjukkan individu yang tenang, tidak mudah tersinggung, dan stabil secara emosi.'),
('K', 'Need to be Forceful', 'Kebutuhan untuk bersikap agresif atau tegas. Skor K tinggi menunjukkan individu yang suka berdebat, terus terang, dan bisa mempertahankan pendapat.'),
('F', 'Need to Follow Rules', 'Kebutuhan untuk mengikuti atasan dan aturan. Skor F tinggi menandakan rasa hormat pada otoritas dan loyalitas.'),
('W', 'Need for Rules and Supervision', 'Kebutuhan akan aturan dan pengawasan yang jelas. Skor W tinggi menunjukkan individu yang merasa nyaman bekerja dengan arahan yang terstruktur.'),
('Z', 'Need to Relate to People', 'Kebutuhan akan hubungan personal yang erat. Skor Z tinggi menunjukkan kebutuhan akan kedekatan dan afeksi, namun seringkali disamakan dengan O.'),
('O', 'Need for Affection and Belonging', 'Kebutuhan akan kasih sayang dan penerimaan. Skor O tinggi menandakan individu yang hangat, simpatik, dan butuh disayangi.');
